        raise ValueError("components_ must have shape [1][2]")
    components_text = "[" + _encode_vector(components[0], 2) + "]"
    return (
        '{"class":"PCA","mean":'
        + mean_text
        + ',"components":'
        + components_text
        + "}"
    )

